const items = $input.all();

// 1. Get requestedTime from webhook input
const requestedTimeRaw = String(
  $('Extract tool-call args').item.json.args.requestedTime || ''
).trim();

// 2. Normalize requestedTime with explicit +00:00 (UTC)
let requestedTimeISO = null;
if (requestedTimeRaw) {
  try {
    // Append +00:00 if no timezone offset is present (e.g. "+02:00" or "-08:00")
    const hasOffset = /[+-]\d{2}:\d{2}$/.test(requestedTimeRaw);
    const withTZ = hasOffset ? requestedTimeRaw : requestedTimeRaw + '+00:00';

    requestedTimeISO = new Date(withTZ).toISOString();
  } catch (e) {
    requestedTimeISO = null;
  }
}

// 3. Extract slots
const slotsObj = items[0]?.json?.slots;
if (!slotsObj || typeof slotsObj !== 'object') {
  return [{ json: { matchFound: false, reason: "no_slots", slots: [] } }];
}

// 4. Normalize slots into ISO
const slotsList = Object.values(slotsObj)
  .flat()
  .map(s => {
    const raw = String(s?.time || '').trim();
    let iso = null;
    try {
      iso = raw ? new Date(raw).toISOString() : null;
    } catch (e) {
      iso = null;
    }
    return { time: raw, iso };
  })
  .filter(s => s.time);

// 5. If no requestedTime → return all slots
if (!requestedTimeISO) {
  return [{
    json: {
      requestedTime: requestedTimeRaw || null,
      requestedTimeISO: null,
      matchFound: false,
      reason: "no_requested_time",
      slots: slotsList.map(s => s.time)
    }
  }];
}

// 6. Find match by comparing actual instants (UTC ms), not raw strings
const hit = slotsList.find(s => {
  if (!s.iso || !requestedTimeISO) return false;
  return new Date(s.iso).getTime() === new Date(requestedTimeISO).getTime();
});

// 7. Return result
return [{
  json: {
    requestedTime: requestedTimeRaw,
    requestedTimeISO,
    matchFound: Boolean(hit),
    slots: hit ? [hit.time] : slotsList.map(s => s.time)
  }
}];

