const raw = $('Extract tool-call args').item.json.args.phone || '';   // <-- change this line
const digits = raw.replace(/[^\d]/g, ''); // keep only numbers

// No phone provided
if (!digits) {
  return { json: { ...$json, phoneE164: null } };
}

let normalized;

// Case 1: Already starts with "1" (and valid length 11 digits total for US)
if (digits.startsWith('1') && digits.length === 11) {
  normalized = digits.slice(1); // remove the country code
}
// Case 2: Local US number (10 digits total)
else if (digits.length === 10) {
  normalized = digits; // US local numbers do NOT have a leading 0
}
// Anything else → invalid
else {
  throw new Error(`Invalid US phone – got "${raw}"`);
}

// Always output in E.164 format
const e164 = '+1' + normalized;

return { json: { ...$json, phoneE164: e164 } };

